import os
import re

from taf.transport.ssh import connect

from ...utils.decorator import IgnoreErrors


class Finder:

    @IgnoreErrors("Finding eNB software version for WMP products failed")
    def find_wmp_sw_version(self, path_dir, prefix=None):
        """Find eNB software version for WMP products.

        :param string path_dir:   Path to directory where TargetBD is available.
        :param string prefix:     BTS software load prefix e.g. LND0.0_ENB_.

        :return:   Found eNB software version.
        :rtype:    string
        """
        return self._find_sw_version(path_dir, prefix)

    @IgnoreErrors("Finding eNB software version for DCM products failed")
    def find_dcm_sw_version(self, path_dir, prefix=None):
        """Find eNB software version for DCM products.

        :param string path_dir:   Path to directory where TargetBD is available.
        :param string prefix:     BTS software load prefix e.g. LND0.0_ENB_.

        :return:   Found eNB software version.
        """
        prefix = "LND0.0_ENB_" if prefix is None else prefix

        sw_version_before_change = self._find_sw_version(path_dir, prefix)
        result = re.search(r"(LND\d+\.\d+_ENB_)(\d{4})(\d*)$", sw_version_before_change)
        if result:
            load, build, date = result.groups()
            return f"{load}{date}_{build}"
        return sw_version_before_change

    def _create_ssh_connection(self, host, username, password):
        ssh_connection = connect(host, username, password)
        return ssh_connection

    def _find_sw_version(self, path_dir, prefix=None):
        if not os.path.exists(path_dir):
            return ""
        targetbd_file = self._find_targetbd_file(path_dir)
        return self._calculate_sw_version(targetbd_file, prefix)

    def _find_targetbd_file(self, path_dir):
        return [
            each for each in os.listdir(path_dir) if re.search("TargetBD.*.xml$", each)
        ][0]

    def _calculate_sw_version(self, targetbd_file, prefix):
        sw_version = re.search("TargetBD_(.*).xml$", targetbd_file).groups()[0]
        return sw_version if prefix is None else f"{prefix}{sw_version}"
